insert into platform_modules(code,title,is_active) values ('46-document-distribution','گردش و توزیع مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده گردش','modules:46-document-distribution:read'),('write','ثبت گردش','modules:46-document-distribution:write'),('delete','حذف گردش','modules:46-document-distribution:delete'),('send','ارسال سند','modules:46-document-distribution:send'),('ack','تأیید دریافت','modules:46-document-distribution:ack'),('cancel','لغو گردش','modules:46-document-distribution:cancel'),('resend','ارسال مجدد','modules:46-document-distribution:resend')) v(a,t,p) where m.code='46-document-distribution' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;