select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('distribution-code','کد گردش سند','text',true,10,'{}'),('document-code','کد سند','text',true,20,'{}'),('document-title','عنوان سند','text',true,30,'{}'),('version','نسخه سند','text',true,40,'{}'),('distribution-type','نوع توزیع','select',true,50,'{"options":["انتشار داخلی","ابلاغ سازمانی","ارسال برای واحد","ارسال برای فرد","اشتراک‌گذاری محدود","اعلام عمومی"]}'),('sender','ارسال‌کننده','text',true,60,'{}'),('recipient','گیرنده','text',true,70,'{}'),('recipient-type','نوع گیرنده','select',true,80,'{"options":["کاربر","واحد سازمانی","نقش","گروه","سازمان"]}'),('access-level','سطح دسترسی','select',true,90,'{"options":["مطالعه","دانلود","چاپ","ویرایش","مدیریت"]}'),('delivery-channel','کانال ابلاغ','select',true,100,'{"options":["داخل سامانه","ایمیل","پیامک","لینک امن","ابلاغ سازمانی"]}'),('sent-at','تاریخ ارسال','text',false,110,'{}'),('due-date','مهلت اقدام','text',false,120,'{}'),('ack-required','نیازمند تأیید دریافت','select',true,130,'{"options":["خیر","بله"]}'),('ack-at','تاریخ تأیید دریافت','text',false,140,'{}'),('distribution-status','وضعیت گردش','select',true,150,'{"options":["پیش‌نویس","در انتظار ارسال","ارسال شده","دریافت شده","مشاهده شده","تأیید دریافت شده","منقضی شده","لغو شده"]}'),('priority','اولویت','select',true,160,'{"options":["عادی","مهم","فوری","بحرانی"]}'),('tracking-reference','مرجع پیگیری','text',false,170,'{}'),('description','توضیحات','textarea',false,180,'{}'),('notes','یادداشت','textarea',false,190,'{}')
) v(k,t,ft,r,s,o) where m.code='46-document-distribution' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
